@@ -1714,0 +1714,8 @@
+static int preload_cmp(const void *i, const void *j) {
+  AOTCodeEntry* ea = *(AOTCodeEntry**)i;
+  AOTCodeEntry* eb = *(AOTCodeEntry**)j;
+  uint a = ea->comp_id();
+  uint b = eb->comp_id();
+  return a > b ? 1 : a < b ? -1 : 0;
+}
